new file mode 100644
index 00000000000..dea79d3b23f
--- /dev/null
+++ b/src/components/views/settings/devices/DeviceDetailHeading.tsx
@@ -0,0 +1,145 @@
+/*
+Copyright 2022 The Matrix.org Foundation C.I.C.
+
