+
+const stateLivenessMap: Map<VoiceBroadcastInfoState, VoiceBroadcastLiveness> = new Map([
+    ["started", "live"],
+    ["resumed", "live"],
+    ["paused", "grey"],
+    ["stopped", "not-live"],
